<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])||($_SESSION['user']['rol']??'')!=='superadmin'){http_response_code(403);exit('Acceso no autorizado.');} $id=(int)($_POST['id']??0);$nombre=trim((string)($_POST['nombre']??''));$eslogan=trim((string)($_POST['eslogan']??''));$telefono=trim((string)($_POST['telefono_whatsapp']??''));$direccion=trim((string)($_POST['direccion']??''));$ciudad=trim((string)($_POST['ciudad']??''));$modalidad=(string)($_POST['modalidad']??'');$estado=(string)($_POST['estado']??'');$comision=(float)($_POST['porcentaje_comision']??0);if(!$id||$nombre===''||$telefono===''||$ciudad===''||!in_array($modalidad,['alquilada_fija','alquilada_comision','administrada'],true)||!in_array($estado,['activa','suspendida','pendiente'],true)||$comision<0||$comision>100){http_response_code(400);exit('Datos no válidos.');}$config=require __DIR__.'/config.php';try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$q=$pdo->prepare('UPDATE tiendas SET nombre=?,eslogan=?,telefono_whatsapp=?,direccion=?,ciudad=?,modalidad=?,porcentaje_comision=?,estado=? WHERE id=?');$q->execute([$nombre,$eslogan,$telefono,$direccion,$ciudad,$modalidad,number_format($comision,2,'.',''),$estado,$id]);header('Location: tiendas-admin.php?updated=1');}catch(Throwable $e){http_response_code(500);exit('No se pudo actualizar la tienda.');}
